package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import android.app.Application;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.local.runtime.*;
import java.nio.file.Files;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;

/** Same original installation cannot evade an uncleared startup by changing typed purpose.
 * Both admissions remain original TaskStore operations; a cleared RPC unknown is not a blacklist. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpLocalStartupFenceNativeTest {
    private static JSONObject review(McpLocalInvocationNativeTest.Fixture x,boolean blockList)throws Exception{JSONObject config=new JSONObject(x.f.config.toString());if(blockList)config.getJSONArray("argv").put("--block-list");return x.owner.mcp("prepareLocalMcpDiscovery",new JSONObject().put("configuration",config));}
    private static JSONObject confirm(McpLocalInvocationNativeTest.Fixture x,JSONObject review)throws Exception{return x.owner.mcp("confirmLocalMcpDiscovery",new JSONObject().put("reviewId",review.getString("reviewId")).put("planDigest",review.getString("planDigest")));}
    private static RuntimeExecutionRef ref(McpLocalInvocationNativeTest.Fixture x,String task)throws Exception{JSONObject job=x.f.tasks.ownerMcpDiscoveryForOwner(task).getJSONObject("nativeJob");return RuntimeExecutionRef.fromHost(job.getJSONObject("exact"),job.getJSONObject("binding"));}
    private static JSONObject settled(McpLocalInvocationNativeTest.Fixture x,String task)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(12);JSONObject result=null;while(System.nanoTime()<until){result=x.owner.mcp("readLocalMcpDiscovery",new JSONObject().put("taskId",task));if(result.optString("status").matches("completed|failed"))return result;Thread.sleep(20);}throw new AssertionError("original discovery failed to settle "+result);}
    private static void stopped(Future<?> work)throws Exception{try{work.get(10,TimeUnit.SECONDS);}catch(ExecutionException known){if(!(known.getCause() instanceof InterruptedException||known.getCause() instanceof SecurityException))throw known;}}
    @Test public void liveOriginalInvokeBlocksOwnerDiscoveryAtTheOriginalCheckoutLeaseBeforeAnotherTaskOrStartup()throws Exception{try(var x=new McpLocalInvocationNativeTest.Fixture("block");var call=x.call()){ExecutorService worker=Executors.newSingleThreadExecutor();try{Future<JSONObject> pending=worker.submit(call::invoke);long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);boolean live=false;while(System.nanoTime()<until){try{if(x.f.runtime.query(call.record().referenceForHost()).json().optString("stderr").contains("CALL_ENTERED")){live=true;break;}}catch(Exception notPublished){}Thread.sleep(20);}assertTrue(live);int tasks=x.f.tasks.list().length();IllegalStateException denied=assertThrows(IllegalStateException.class,()->review(x,false));assertTrue(denied.getMessage().contains("holds_checkout"));assertEquals(tasks,x.f.tasks.list().length());assertEquals(1,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));call.control.cancel();stopped(pending);}finally{call.control.cancel();worker.shutdownNow();}}}
    @Test public void liveOriginalDiscoveryMakesTaskInvokeTypedNotDispatchedWithoutAnySecondStartup()throws Exception{String program=McpLocalInvocationNativeTest.python("ok").replace(" elif method=='tools/list':\n"," elif method=='tools/list':\n  if '--block-list' in sys.argv: time.sleep(20)\n");try(var x=new McpLocalInvocationNativeTest.Fixture("python3","server.py",program);var call=x.call()){String discovery=confirm(x,review(x,true)).getString("taskId");try{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);boolean live=false;while(System.nanoTime()<until){try{if(x.f.runtime.query(ref(x,discovery)).json().optString("stderr").contains("ACTUAL_METHOD:tools/list")){live=true;break;}}catch(Exception notPublished){}Thread.sleep(20);}assertTrue(live);JSONObject result=call.invoke();assertEquals(result.toString(),"failed",result.getString("status"));assertTrue(result.getBoolean("nativeHostNeverEnteredDispatch"));assertFalse(result.getBoolean("dispatched"));assertFalse(result.getBoolean("nativeProcessReceiptAvailable"));assertEquals(0,x.f.tasks.localMcpInvocationsForOwner(call.task).size());assertFalse(Files.exists(x.copy(call.operation)));assertEquals(1,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}finally{x.owner.mcp("cancelLocalMcpDiscovery",new JSONObject().put("taskId",discovery));assertEquals("failed",settled(x,discovery).getString("status"));}}}
    @Test public void previouslyAdmittedInvokeAndQueuedOwnerIntentStillShareTheOneOriginalCheckoutLease()throws Exception{try(var x=new McpLocalInvocationNativeTest.Fixture("block");var call=x.call()){call.approve();call.operation=call.journal.beginOperation(x.tool,new JSONObject(call.arguments.toString()));JSONObject capability=call.capability(),approved=x.f.tasks.requireCapabilityApproval(call.task,call.run,x.tool,call.arguments,capability);try(var program=x.f.plugins.localMcpProgramForTask(call.nativeInput(),x.tool,call.control)){var admitted=x.f.tasks.admitLocalMcpInvocationForHost(call.task,call.run,call.epoch,x.tool,call.operation,call.arguments,capability,approved.getString("approvalId"),program,call.control);JSONObject ownerReview=review(x,false);var field=dev.pocketengine.features.FeatureHost.class.getDeclaredField("workers");field.setAccessible(true);ThreadPoolExecutor original=(ThreadPoolExecutor)field.get(x.host);CountDownLatch occupied=new CountDownLatch(original.getCorePoolSize()),release=new CountDownLatch(1);ExecutorService invocation=Executors.newSingleThreadExecutor();String discovery=null;try{for(int i=0;i<original.getCorePoolSize();i++)original.execute(()->{occupied.countDown();try{release.await(10,TimeUnit.SECONDS);}catch(InterruptedException cancelled){Thread.currentThread().interrupt();}});assertTrue(occupied.await(8,TimeUnit.SECONDS));discovery=confirm(x,ownerReview).getString("taskId");assertEquals("prepared",x.f.tasks.ownerMcpDiscoveryForOwner(discovery).getString("operationState"));Future<JSONObject> actual=invocation.submit(()->McpLocalTaskPipe.run(admitted,x.f.tasks,x.f.local,null));long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);boolean live=false;while(System.nanoTime()<until){try{if(x.f.runtime.query(call.record().referenceForHost()).json().optString("stderr").contains("CALL_ENTERED")){live=true;break;}}catch(Exception notPublished){}Thread.sleep(20);}assertTrue(live);assertEquals(1,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));release.countDown();JSONObject failed=settled(x,discovery);assertEquals(failed.toString(),"failed",failed.getString("status"));assertTrue(failed.getJSONObject("receipt").getBoolean("nativeHostNeverEnteredDispatch"));assertFalse(failed.getJSONObject("receipt").getBoolean("nativeProcessReceiptAvailable"));assertFalse(Files.exists(x.copy(discovery).resolve("START_EFFECT")));assertTrue(Files.exists(x.copy(call.operation).resolve("START_EFFECT")));call.control.cancel();stopped(actual);assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}finally{release.countDown();call.control.cancel();if(discovery!=null){x.owner.mcp("cancelLocalMcpDiscovery",new JSONObject().put("taskId",discovery));settled(x,discovery);}invocation.shutdownNow();}}}}
    @Test public void onlyBusinessRpcUnknownAfterRealProcessCleanupDoesNotBanExplicitIndependentOwnerDiscovery()throws Exception{try(var x=new McpLocalInvocationNativeTest.Fixture("lost");var call=x.call()){JSONObject result=call.invoke();call.journal.finishOperation(call.operation,result);assertEquals("unknown",result.getString("status"));assertTrue(result.getJSONObject("nativeMcp").getBoolean("processSettled"));String before=call.record().publicReceiptForHost().toString();String fresh=confirm(x,review(x,false)).getString("taskId");assertEquals("completed",settled(x,fresh).getString("status"));assertTrue(Files.exists(x.copy(fresh).resolve("START_EFFECT")));assertFalse(Files.exists(x.copy(fresh).resolve("RPC_EFFECT")));assertEquals(before,call.record().publicReceiptForHost().toString());}}
}
